    function getCtx() {
        try {
            return SillyTavern.getContext?.() || null;
        } catch (e) {
            return null;
        }
    }

    function getSettings() {
        const ctx = getCtx();
        const stored = ctx?.extensionSettings?.[PLUGIN_ID] || window.extension_settings?.[PLUGIN_ID] || {};
        let ls = {};
        try {
            const raw = localStorage.getItem(LS_KEY);
            if (raw) ls = JSON.parse(raw) || {};
        } catch (e) { /* ignore */ }
        // 服务器配置升级后丢弃旧缓存，平滑升级到最新版本。
        if ((Number(stored.configVersion) || 0) < 7) {
            delete stored.presets;
            delete stored.subPrompts;
        }
        if ((Number(ls.configVersion) || 0) < 7) {
            delete ls.presets;
            delete ls.subPrompts;
        }
        if ((Number(stored.configVersion) || 0) > (Number(ls.configVersion) || 0)) {
            ls = Object.fromEntries(['enableJailbreak', 'jailbreakPrompt', 'enableNovelBypass', 'novelBypassPrompt'].filter(key => Object.hasOwn(ls, key)).map(key => [key, ls[key]]));
        }
        const merged = Object.assign({}, DEFAULT_SETTINGS, stored, ls);
        merged.configVersion = 7;
        merged.autoSend = merged.autoSend !== false;
        merged.enableWorldInfo = (ls.enableWorldInfo ?? stored.enableWorldInfo) !== false;
        merged.worldInfoSelections = ls.worldInfoSelections || stored.worldInfoSelections || null;
        merged.worldInfoOverrides = ls.worldInfoOverrides || stored.worldInfoOverrides || null;
        merged.customWorldInfoEntries = Array.isArray(ls.customWorldInfoEntries || stored.customWorldInfoEntries)
            ? (ls.customWorldInfoEntries || stored.customWorldInfoEntries)
            : [];
        merged.factions = Array.isArray(ls.factions || stored.factions) ? (ls.factions || stored.factions) : [];
        merged.defaultTurns = Math.min(30, Math.max(1, Math.floor(Number(merged.defaultTurns) || DEFAULT_SETTINGS.defaultTurns)));
        merged.subConfig = Object.assign({}, DEFAULT_SETTINGS.subConfig);
        const storedSub = ls.subConfig || stored.subConfig || {};
        for (const k of Object.keys(DEFAULT_SETTINGS.subConfig)) {
            merged.subConfig[k] = Object.assign({}, DEFAULT_SETTINGS.subConfig[k], storedSub[k] || {});
        }
        merged.subPrompts = Object.assign({}, ls.subPrompts || stored.subPrompts || {});
        merged.presets = ls.presets || stored.presets || null;
        merged.enableJailbreak = (ls.enableJailbreak ?? stored.enableJailbreak) !== false;
        merged.jailbreakPrompt = (ls.jailbreakPrompt ?? stored.jailbreakPrompt) || '';
        merged.enableNovelBypass = (ls.enableNovelBypass ?? stored.enableNovelBypass) !== false;
        merged.novelBypassPrompt = (ls.novelBypassPrompt ?? stored.novelBypassPrompt) || '';
        return merged;
    }

    function getJailbreakPrompt(settings) {
        const s = settings || getSettings();
        if (s.enableJailbreak === false) return '';
        const userPrompt = s.jailbreakPrompt && typeof s.jailbreakPrompt === 'string' ? s.jailbreakPrompt.trim() : '';
        // 若用户保存的是旧版未缝合约定（未包含 roleplay_and_writing_constraints 且长度小于 1000），平滑升级为完整缝合版
        if (userPrompt && !userPrompt.includes('roleplay_and_writing_constraints') && userPrompt.length < 1000) {
            return DEFAULT_JAILBREAK_PROMPT;
        }
        return userPrompt || DEFAULT_JAILBREAK_PROMPT;
    }

    function getNovelBypassPrompt(settings) {
        const s = settings || getSettings();
        if (s.enableNovelBypass === false) return '';
        const userPrompt = s.novelBypassPrompt && typeof s.novelBypassPrompt === 'string' ? s.novelBypassPrompt.trim() : '';
        return userPrompt || DEFAULT_NOVEL_BYPASS_PROMPT;
    }

    function getSubPrompt(eventKey, genreOrFeatureKey, settings) {
        const s = settings || getSettings();
        const fullKey = `${eventKey}.${genreOrFeatureKey}`;
        const userPrompt = s.subPrompts && typeof s.subPrompts[fullKey] === 'string' ? s.subPrompts[fullKey].trim() : '';

        // 若用户保存的为旧版本极简单行模板（长度小于70），平滑升级为最新详尽版
        if (userPrompt) {
            return userPrompt;
        }
        if (DEFAULT_SUB_PROMPTS[fullKey]) {
            return DEFAULT_SUB_PROMPTS[fullKey];
        }
        const conf = SUB_CONFIGS[eventKey];
        const genre = conf?.genres?.find(g => g.key === genreOrFeatureKey);
        return genre?.prompt || '';
    }

    function getPreset(typeKey, settings) {
        const s = settings || getSettings();
        const userPreset = s.presets?.[typeKey];
        if (userPreset && typeof userPreset.systemPrompt === 'string' && userPreset.systemPrompt.trim()) {
            return userPreset;
        }
        return DEFAULT_PRESETS[typeKey] || DEFAULT_PRESETS.random;
    }

    function applyTheme(themeId) {
        const targetTheme = THEMES.find(t => t.id === themeId) || THEMES.find(t => t.id === DEFAULT_SETTINGS.theme);
        const actualId = targetTheme.id;
        if (root) {
            root.setAttribute('data-theme', actualId);
            const pillText = root.querySelector('#se-theme-name');
            if (pillText) pillText.textContent = targetTheme.name;
            const pillDot = root.querySelector('.se-theme-pill-dot');
            if (pillDot) pillDot.style.background = targetTheme.color;

            const themeSelect = root.querySelector('#se-theme-select');
            if (themeSelect && themeSelect.value !== actualId) {
                themeSelect.value = actualId;
            }
        }
        const cards = root?.querySelectorAll('.se-theme-card');
        if (cards) {
            cards.forEach(card => {
                if (card.dataset.themeId === actualId) {
                    card.classList.add('active');
                } else {
                    card.classList.remove('active');
                }
            });
        }
    }

    function selectTheme(themeId) {
        const theme = THEMES.find(t => t.id === themeId) || THEMES[0];
        const s = getSettings();
        s.theme = theme.id;
        persistSettings(s);
        applyTheme(theme.id);
        if (window.toastr) {
            toastr.info('已切换主题：' + theme.name);
        }
    }

    function cycleTheme() {
        const s = getSettings();
        const currentId = s.theme || 'ocean';
        const idx = THEMES.findIndex(t => t.id === currentId);
        const nextIdx = (idx + 1) % THEMES.length;
        selectTheme(THEMES[nextIdx].id);
    }

    function persistSettings(settings) {
        const clean = Object.assign({}, DEFAULT_SETTINGS, settings || {}, {configVersion: 7});
        const ctx = getCtx();
        if (ctx?.extensionSettings) ctx.extensionSettings[PLUGIN_ID] = clean;
        if (window.extension_settings) window.extension_settings[PLUGIN_ID] = clean;
        try {
            localStorage.setItem(LS_KEY, JSON.stringify(clean));
        } catch (e) { /* ignore */ }
        try {
            if (typeof ctx?.saveSettingsDebounced === 'function') ctx.saveSettingsDebounced();
            else if (typeof window.saveSettingsDebounced === 'function') window.saveSettingsDebounced();
            else if (typeof saveSettingsDebounced === 'function') saveSettingsDebounced();
            else if (typeof window.saveSettings === 'function') window.saveSettings();
        } catch (e) {
            console.warn('[ST Direct] 保存设置失败:', e);
        }
    }

    function getChatState() {
        const ctx = getCtx();
        if (!ctx || !ctx.chatMetadata) return { counters: {}, events: [] };
        if (!ctx.chatMetadata.extensions) ctx.chatMetadata.extensions = {};
        if (!ctx.chatMetadata.extensions[PLUGIN_ID]) ctx.chatMetadata.extensions[PLUGIN_ID] = { counters: {}, events: [] };
        const state = ctx.chatMetadata.extensions[PLUGIN_ID];
        if (!state.counters || typeof state.counters !== 'object') state.counters = {};
        if (!Array.isArray(state.events)) state.events = [];
        return state;
    }

    async function saveChatState() {
        const ctx = getCtx();
        try {
            if (typeof ctx?.saveChat === 'function') {
                await ctx.saveChat();
                return;
            }
            const script = await import('/script.js');
            if (typeof script.saveChatConditional === 'function') await script.saveChatConditional();
            else if (typeof window.saveChatConditional === 'function') await window.saveChatConditional();
        } catch (e) {
            console.warn('[ST Direct] 保存聊天数据失败:', e);
        }
    }

    // ========== 初始化 ==========

    const WAND_MENU_ITEM_ID = 'se-wand-menu-item';

    function findExtensionsMenu() {
        const candidates = [
            '#extensionsMenu',
            '#extensions_menu',
            '.extensions_menu',
            '#rm_button_panel_extensions_menu',
            '#extensionsMenuButton + div',
            '[id*="extensionsMenu"]',
        ];
        for (const sel of candidates) {
            const el = document.querySelector(sel);
            if (el) return el;
        }
        const c = document.querySelector('.extension_container');
        if (c && c.parentElement) return c.parentElement;
        return null;
    }

    function injectWandMenuButton() {
        const tryInject = () => {
            const menu = findExtensionsMenu();
            if (!menu) return false;
            if (document.getElementById(WAND_MENU_ITEM_ID)) return true;

            const container = document.createElement('div');
            container.className = 'extension_container se-wand-container';

            const item = document.createElement('div');
            item.id = WAND_MENU_ITEM_ID;
            item.className = 'list-group-item flex-container flexGap5 interactable se-wand-item';
            item.tabIndex = 0;
            item.setAttribute('role', 'button');
            item.setAttribute('title', '剧情导演');
            item.innerHTML = `
                <i class="fa-solid fa-clapperboard extensionsMenuExtensionButton"></i>
                <span class="se-wand-label">剧情导演</span>
            `;

            let handled = false;
            const triggerOpen = (e) => {
                if (handled) return;
                handled = true;
                setTimeout(() => { handled = false; }, 350);
                if (e) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (e.stopImmediatePropagation) e.stopImmediatePropagation();
                }
                togglePanel();
                if (window.$ && $('#extensionsMenu').length) {
                    $('#extensionsMenu').hide();
                } else if (menu) {
                    menu.style.display = 'none';
                }
            };

            item.addEventListener('pointerup', (e) => {
                if (e.pointerType === 'mouse' && e.button !== 0) return;
                triggerOpen(e);
            });
            item.addEventListener('click', triggerOpen);
            item.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                    triggerOpen(e);
                }
            });

            container.appendChild(item);
            menu.appendChild(container);
            return true;
        };

        tryInject();
        // 持续保持挂载（每秒检查一次，极度轻量，杜绝聊天或卡片切换后丢失）
        setInterval(tryInject, 1000);

        // 监听魔杖按钮各类交互事件，触发即时快速挂载
        const onWandInteract = (e) => {
            if (e.target.closest('#extensionsMenuButton, .extensionsMenuExtensionButton, #leftSendForm')) {
                setTimeout(tryInject, 20);
                setTimeout(tryInject, 100);
            }
        };
        document.addEventListener('pointerdown', onWandInteract, true);
        document.addEventListener('click', onWandInteract, true);
    }

    function installExtensionsDrawerEntry() {
        const tryInstallDrawer = () => {
            if (document.getElementById('se-drawer-entry')) return true;
            const host = document.querySelector('#extensions_settings2, #extensions_settings');
            if (!host) return false;

            const entry = document.createElement('div');
            entry.id = 'se-drawer-entry';
            entry.className = 'se-drawer-entry';
            entry.innerHTML = `
                <div class="inline-drawer">
                    <div class="inline-drawer-toggle inline-drawer-header">
                        <b><i class="fa-solid fa-clapperboard" style="color:var(--se-accent, #38bdf8); margin-right:6px;"></i>剧情导演</b>
                        <div class="inline-drawer-icon fa-solid fa-circle-chevron-down down"></div>
                    </div>
                    <div class="inline-drawer-content">
                        <p style="font-size:12px; color:var(--SmartThemeQuoteColor, #94a3b8); margin:6px 0 10px 0;">
                            独立的副模型剧情事件导演。支持多回合博弈、暗箱档案与自适应破限。
                        </p>
                        <button id="se-drawer-open-btn" class="menu_button" type="button" style="width:100%;">
                            打开剧情导演面板
                        </button>
                    </div>
                </div>
            `;
            entry.querySelector('#se-drawer-open-btn')?.addEventListener('click', () => {
                togglePanel();
            });
            host.appendChild(entry);
            return true;
        };

        if (tryInstallDrawer()) return;
        const drawerTimer = setInterval(() => {
            if (tryInstallDrawer()) clearInterval(drawerTimer);
        }, 1000);
    }

    function setupSlashCommand() {
        try {
            const ctx = SillyTavern.getContext?.() || null;
            const SlashCommandParser = ctx?.SlashCommandParser || window.SlashCommandParser;
            const SlashCommand = ctx?.SlashCommand || window.SlashCommand;
            if (!SlashCommandParser || !SlashCommand) return;
            SlashCommandParser.addCommandObject(SlashCommand.fromProps({
                name: 'direct',
                aliases: ['st-direct', 'director'],
                helpString: '打开/关闭剧情导演面板。',
                callback: async () => { togglePanel(); return ''; },
            }));
        } catch (e) {
            console.debug('[ST Direct] 斜杠命令注册略过', e);
        }
    }

    function init() {
        if (initialized) return;
        initialized = true;
        try {
            mountUI();
            bindSTEvents();
            updateFloatingCapsule();
            injectWandMenuButton();
            installExtensionsDrawerEntry();
            setupSlashCommand();
            console.log('[ST Direct] 剧情导演 v0.5.0 已启动（独立系统纸条 + 分轮暗箱）');
            if (window.toastr) {
                toastr.success('剧情导演 v0.5.0 已加载（独立系统纸条与分轮暗箱已就绪）', '', { timeOut: 2500 });
            }
            
        } catch (e) {
            console.warn('[ST Direct] 初始化失败:', e);
        }
    }

    let initTimer = null;
    function startInit() {
        if (initTimer) return;
        try {
            bindSTEvents();
        } catch (e) { /* ignore */ }

        try {
            const ctx = getCtx();
            const eventSource = ctx?.eventSource || window.eventSource;
            const eventTypes = ctx?.eventTypes || window.event_types;
            if (eventSource && eventTypes?.APP_READY && typeof eventSource.on === 'function') {
                eventSource.on(eventTypes.APP_READY, init);
            }
        } catch (e) {
            console.warn('[ST Direct] 订阅 APP_READY 失败(忽略):', e);
        }

        const t0 = Date.now();
        initTimer = setInterval(() => {
            const ok = !!(window.SillyTavern || window.extension_settings);
            if (ok || Date.now() - t0 > 3500) {
                clearInterval(initTimer);
                initTimer = null;
                try {
                    init();
                } catch (e) {
                    console.warn('[ST Direct] 初始化异常:', e);
                }
            }
        }, 250);
    }

