    async function askLLM(type, context, settings, eventId, parentSignal) {
        if (parentSignal?.aborted) {
            const err = new Error('用户已取消生成');
            err.name = 'AbortError';
            throw err;
        }

        const base = cleanBaseUrl(settings.baseUrl);
        if (!base || !settings.apiKey || !settings.model) throw new Error('LLM 配置不完整');

        if (settings.enableWorldInfo !== false) {
            try { await refreshWorldInfoCache(settings); } catch (e) { /* ignore */ }
        }

        const payload = {
            model: settings.model,
            temperature: Number.isFinite(Number(settings.temperature)) ? Math.min(2, Math.max(0, Number(settings.temperature))) : DEFAULT_SETTINGS.temperature,
            max_tokens: Number(settings.maxTokens) || DEFAULT_SETTINGS.maxTokens,
            messages: buildEventPrompt(type, context, settings, cachedWorldInfoEntries),
        };

        const urls = [];
        if (/\/v1$/i.test(base)) {
            urls.push(base + '/chat/completions');
            urls.push(base.replace(/\/v1$/i, '') + '/chat/completions');
        } else {
            urls.push(base + '/chat/completions');
            urls.push(base + '/v1/chat/completions');
            urls.push(base + '/api/v1/chat/completions');
        }

        const log = {
            time: new Date().toLocaleTimeString(),
            type: type.label,
            eventId: eventId || '',
            url: urls[0],
            payload,
            status: 'pending',
            response: '',
            error: '',
        };
        pushApiLog(log);

        let lastError = null;
        let retriedEmpty = false;
        for (const url of urls) {
            if (parentSignal?.aborted) {
                lastError = new Error('用户已取消生成');
                lastError.name = 'AbortError';
                break;
            }

            log.url = url;
            const controller = new AbortController();
            const timer = setTimeout(() => controller.abort(), 300000);

            const abortHandler = () => controller.abort();
            if (parentSignal) {
                parentSignal.addEventListener('abort', abortHandler, { once: true });
            }

            try {
                const res = await fetchWithProxyFallback(url, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    'Authorization': 'Bearer ' + settings.apiKey.trim(),
                    },
                    body: JSON.stringify(payload),
                    signal: controller.signal,
                }, settings.requestTransport);
                if (!res.ok) {
                    lastError = new Error(res.status === 401
                        ? 'HTTP 401：请求未通过鉴权。请检查插件 API Key；使用代理时也需保持酒馆登录。代理不能修复无效密钥。'
                        : 'HTTP ' + res.status);
                    if (res.status === 404 || res.status === 405) continue;
                    break;
                }
                const data = await safeParseJsonResponse(res, '副 API 生成');
                const parsedResponse = readCompletionBody(data);
                log.diagnostic = parsedResponse.diagnostic;
                const content = parsedResponse.content;
                if (typeof content === 'string' && content.trim()) {
                    let cleanedContent = content.trim();
                    const outlineIdx = cleanedContent.search(/<(?:event_outline|event_archive)>/i);
                    if (outlineIdx > 0) {
                        cleanedContent = cleanedContent.slice(outlineIdx).trim();
                    }
                    log.status = 'success';
                    log.response = cleanedContent;
                    lastRawModelOutput = {
                        time: new Date().toLocaleTimeString(),
                        type: type.label,
                        eventId: eventId || '',
                        content: content.trim()
                    };
                    renderApiLogs();
                    return cleanedContent;
                }
                lastError = new Error(parsedResponse.error);
                if (parsedResponse.retryable && !retriedEmpty) {
                    retriedEmpty = true;
                    log.emptyResponseRetried = true;
                    urls.splice(urls.indexOf(url) + 1, 0, url);
                    continue;
                }
                break;
            } catch (err) {
                if (parentSignal?.aborted) {
                    lastError = new Error('用户已取消生成');
                    lastError.name = 'AbortError';
                    break;
                }
                lastError = err?.name === 'AbortError' ? new Error('请求超时（5分钟），请检查模型或降低输出上限') : err;
                break;
            } finally {
                clearTimeout(timer);
                if (parentSignal) {
                    parentSignal.removeEventListener('abort', abortHandler);
                }
            }
        }

        if (parentSignal?.aborted) {
            log.status = 'cancelled';
            log.error = '用户已取消生成';
        } else {
            log.status = 'error';
            log.error = lastError?.message || 'LLM 请求失败';
        }
        renderApiLogs();
        throw lastError || new Error('LLM 请求失败');
    }

